#!/usr/bin/env bash
# Sync Nova Canvas shared prompts across OpenCode / Continue / GitHub ends.
#
# Canonical sources (edit these by hand):
#   AGENTS.md                          repo conventions (GitHub end; OpenCode auto-reads it)
#   canvas-agent/agent-instructions.md canvas-agent runtime behavior
# Generated, do-NOT-edit artifacts (regenerated by this script):
#   .continue/rules/nova-canvas-conventions.mdc   Continue end (conventions + agent instructions)
#   .agents/skills/nova-canvas-agent/SKILL.md       OpenCode end (agent instructions as a skill)
#
# Usage:
#   bash scripts/sync-prompts.sh          write the derived ends
#   bash scripts/sync-prompts.sh --check  verify in sync, exit 1 on drift (for CI)
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
AGENTS="$REPO_ROOT/AGENTS.md"
AGENT="$REPO_ROOT/canvas-agent/agent-instructions.md"

CHECK=0
if [ "${1:-}" = "--check" ]; then CHECK=1; fi

agents=$(cat "$AGENTS")
agent=$(cat "$AGENT")

AUTOGEN='<!-- AUTO-GENERATED by scripts/sync-prompts — do not edit. Edit AGENTS.md / canvas-agent/agent-instructions.md and re-run. -->'

mdc_body="$AUTOGEN

# Nova Canvas (启画) — 共享提示（同步源）

以下由 AGENTS.md 与 canvas-agent/agent-instructions.md 合并生成，请勿手改。

--- AGENTS.md ---

$agents

--- canvas-agent/agent-instructions.md ---

$agent"

mdc="---
name: nova-canvas-conventions
description: Nova Canvas (启画) shared conventions + canvas-agent instructions, synced from AGENTS.md and canvas-agent/agent-instructions.md.
alwaysApply: true
---

$mdc_body"

skill_body="$AUTOGEN

$agent"

skill="---
name: nova-canvas-agent
description: Runtime instructions for operating the Nova Canvas agent via canvas MCP tools (canvas_get_state, canvas_apply_ops, workbench_image_*, etc.).
---

$skill_body"

MDC_PATH="$REPO_ROOT/.continue/rules/nova-canvas-conventions.mdc"
SKILL_PATH="$REPO_ROOT/.agents/skills/nova-canvas-agent/SKILL.md"

write_file() {
  mkdir -p "$(dirname "$1")"
  printf '%s' "$2" > "$1"
}

if [ "$CHECK" = 1 ]; then
  drift=0
  if [ ! -f "$MDC_PATH" ] || ! diff -q <(printf '%s' "$mdc" | sed 's/\r$//') <(sed 's/\r$//' "$MDC_PATH") >/dev/null; then
    echo "DRIFT: $MDC_PATH"; drift=1
  fi
  if [ ! -f "$SKILL_PATH" ] || ! diff -q <(printf '%s' "$skill" | sed 's/\r$//') <(sed 's/\r$//' "$SKILL_PATH") >/dev/null; then
    echo "DRIFT: $SKILL_PATH"; drift=1
  fi
  if [ "$drift" = 1 ]; then exit 1; fi
  echo "OK: all prompt ends in sync."
  exit 0
else
  write_file "$MDC_PATH" "$mdc"
  write_file "$SKILL_PATH" "$skill"
  echo "Wrote: $MDC_PATH"
  echo "Wrote: $SKILL_PATH"
  exit 0
fi
